/* @autogenerated */
package net.civeira.phylax.feature.oauth.webauthn.infrastructure.driven;

import java.time.OffsetDateTime;
import java.time.temporal.ChronoUnit;
import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.oauth.webauthn.domain.WebAuthnCredential;
import net.civeira.phylax.feature.oauth.webauthn.domain.exception.WebAuthnException;
import net.civeira.phylax.testing.sql.OidcRepositories;

/** The passkeys of the users stored with the generated repositories on h2. */
class WebAuthnCredentialAdapterUnitTest {
  private OidcRepositories store;
  private WebAuthnCredentialAdapter credentials;
  private String tenant;
  private String alice;
  private String bob;

  @BeforeEach
  void setUp() {
    store = new OidcRepositories();
    tenant = store.tenant("acme");
    alice = store.user(tenant, "alice", "alice@acme.test");
    bob = store.user(tenant, "bob", "bob@acme.test");
    credentials = new WebAuthnCredentialAdapter();
    credentials.reader = store.webauthn();
    credentials.writer = store.webauthnWriter();
    credentials.users = store.users();
  }

  private void register(String user, String credentialId, boolean enabled) {
    credentials.store(WebAuthnCredential.builder().userUid(user).credentialId(credentialId)
        .publicKey("pk-" + credentialId).signCount(3).aaguid("aaguid-1")
        .deviceName("Laptop " + credentialId).transports(List.of("usb", "nfc")).enabled(enabled)
        .build());
  }

  @Test
  @DisplayName("A stored passkey is found by its credential id with the user and its transports")
  void store_and_find() {
    register(alice, "cred-1", true);

    WebAuthnCredential found = credentials.findByCredentialId("cred-1", tenant).orElseThrow();
    Assertions.assertEquals(alice, found.getUserUid());
    Assertions.assertEquals("alice@acme.test", found.getUsername(), "The username is the email");
    Assertions.assertEquals("pk-cred-1", found.getPublicKey());
    Assertions.assertEquals(3, found.getSignCount());
    Assertions.assertEquals("aaguid-1", found.getAaguid().orElseThrow());
    Assertions.assertEquals("Laptop cred-1", found.getDeviceName().orElseThrow());
    Assertions.assertEquals(List.of("usb", "nfc"), found.getTransports().orElseThrow(),
        "The transports are stored as a json array");
    Assertions.assertTrue(found.isEnabled());
    Assertions.assertTrue(credentials.findByCredentialId("missing", tenant).isEmpty());
  }

  @Test
  @DisplayName("A passkey registered disabled stays disabled and without transports")
  void store_disabled() {
    credentials.store(WebAuthnCredential.builder().userUid(alice).credentialId("cred-2")
        .publicKey("pk").signCount(0).enabled(false).build());

    WebAuthnCredential found = credentials.findByCredentialId("cred-2", tenant).orElseThrow();
    Assertions.assertFalse(found.isEnabled());
    Assertions.assertTrue(found.getTransports().isEmpty());
    Assertions.assertEquals("cred-2",
        store.value("SELECT name FROM access_user_webauthn_credential"),
        "Without a device name the credential id names the passkey");
  }

  @Test
  @DisplayName("Two passkeys with the same device name get distinct names for the same user")
  void same_device_name() {
    for (String id : new String[] {"key-1", "key-2", "key-3"}) {
      credentials.store(WebAuthnCredential.builder().userUid(alice).credentialId(id).publicKey("pk")
          .signCount(0).deviceName("YubiKey").enabled(true).build());
    }
    credentials.store(WebAuthnCredential.builder().userUid(bob).credentialId("key-b")
        .publicKey("pk").signCount(0).deviceName("YubiKey").enabled(true).build());

    Assertions.assertEquals("YubiKey,YubiKey (2),YubiKey (3)", store.value(
        "SELECT LISTAGG(name, ',') WITHIN GROUP (ORDER BY name) FROM access_user_webauthn_credential"
            + " WHERE `user` = '" + alice + "'"));
    Assertions.assertEquals("YubiKey",
        store
            .value("SELECT name FROM access_user_webauthn_credential WHERE `user` = '" + bob + "'"),
        "The names are unique by user");
    Assertions.assertEquals("YubiKey",
        credentials.findByCredentialId("key-2", tenant).orElseThrow().getDeviceName().orElseThrow(),
        "The device name is kept as reported");
  }

  @Test
  @DisplayName("The passkeys are listed by user")
  void find_by_user() {
    register(alice, "cred-a1", true);
    register(alice, "cred-a2", true);
    register(bob, "cred-b1", true);

    Assertions.assertEquals(2, credentials.findByUser(alice, tenant).size());
    Assertions.assertEquals(List.of("cred-b1"), credentials.findByUser(bob, tenant).stream()
        .map(WebAuthnCredential::getCredentialId).toList());
  }

  @Test
  @DisplayName("An assertion updates the sign counter and the last use")
  void update_sign_count() {
    register(alice, "cred-1", true);
    OffsetDateTime used = OffsetDateTime.now().truncatedTo(ChronoUnit.SECONDS);

    credentials.updateSignCount("cred-1", tenant, 9, used);

    WebAuthnCredential found = credentials.findByCredentialId("cred-1", tenant).orElseThrow();
    Assertions.assertEquals(9, found.getSignCount());
    Assertions.assertEquals(used.toInstant(), found.getLastUsedAt().orElseThrow().toInstant());
    Assertions.assertThrows(WebAuthnException.class,
        () -> credentials.updateSignCount("missing", tenant, 1, used));
  }

  @Test
  @DisplayName("A rename to a name already used by another passkey of the user gets a suffix")
  void rename_to_taken_name() {
    register(alice, "cred-1", true);
    register(alice, "cred-2", true);
    register(bob, "cred-b", true);
    credentials.rename("cred-b", bob, tenant, "Phone");

    credentials.rename("cred-1", alice, tenant, "Phone");
    credentials.rename("cred-2", alice, tenant, "Phone");
    Assertions.assertEquals("Phone,Phone (2)", store.value(
        "SELECT LISTAGG(name, ',') WITHIN GROUP (ORDER BY name) FROM access_user_webauthn_credential"
            + " WHERE `user` = '" + alice + "'"),
        "Only the names of the same user collide");

    credentials.rename("cred-1", alice, tenant, "Phone");
    Assertions.assertEquals("Phone",
        store.value(
            "SELECT name FROM access_user_webauthn_credential" + " WHERE authenticator = 'cred-1'"),
        "Keeping its own name adds no suffix");
  }

  @Test
  @DisplayName("Only the owner renames or deletes a passkey")
  void rename_and_delete() {
    register(alice, "cred-1", true);

    credentials.rename("cred-1", alice, tenant, "Phone");
    Assertions.assertEquals("Phone",
        store.value("SELECT name FROM access_user_webauthn_credential"));
    Assertions.assertThrows(WebAuthnException.class,
        () -> credentials.rename("cred-1", bob, tenant, "Stolen"));
    Assertions.assertThrows(WebAuthnException.class,
        () -> credentials.delete("cred-1", bob, tenant));

    credentials.delete("cred-1", alice, tenant);
    Assertions.assertTrue(credentials.findByUser(alice, tenant).isEmpty());
  }
}
